-- Fase 0 / 04: serie mensual MODIS (por satélite y versión) vs S-NPP, jul-2020 a jun-2024. Solo lectura.
SET work_mem = '256MB';
\copy (WITH m AS ( SELECT date_trunc('month', acq_date)::date AS mes, satellite, version, count(*) AS n_total, count(*) FILTER (WHERE type = 0) AS n_t0, count(*) FILTER (WHERE type = 0 AND confidence >= 30) AS n_t0_conf, sum(frp) FILTER (WHERE type = 0) AS frp_t0, percentile_cont(0.5) WITHIN GROUP (ORDER BY frp) FILTER (WHERE type = 0) AS frp_med, percentile_cont(0.1) WITHIN GROUP (ORDER BY frp) FILTER (WHERE type = 0) AS frp_p10, min(frp) FILTER (WHERE type = 0 AND frp > 0) AS frp_min_pos, avg((confidence >= 80)::int) FILTER (WHERE type = 0) AS frac_conf_alta, avg((confidence < 30)::int) FILTER (WHERE type = 0) AS frac_conf_baja, avg((daynight = 'D')::int) AS frac_dia, avg(scan) AS scan_medio, count(*) FILTER (WHERE frp <= 0) AS n_frp_le0 FROM modis WHERE acq_date >= '2020-07-01' AND acq_date < '2024-07-01' GROUP BY 1,2,3 ), s AS ( SELECT date_trunc('month', acq_date)::date AS mes, count(*) FILTER (WHERE type = 0) AS s_n_t0, count(*) FILTER (WHERE type = 0 AND confidence <> 'l') AS s_n_t0_conf, sum(frp) FILTER (WHERE type = 0) AS s_frp_t0 FROM viirs_suomi WHERE acq_date >= '2020-07-01' AND acq_date < '2024-07-01' GROUP BY 1 ) SELECT * FROM m JOIN s USING (mes) ORDER BY satellite, mes) TO 'serie_mensual.csv' WITH (FORMAT csv, HEADER)
